package aquanet;

import java.util.*;

/** AquaNet console demonstration: water assets, observations, reports, demand and operator assignments. */
public class AquaNetApp {
    record Asset(String id,String type,String location) {}
    record Observation(String sensor,double level,double ph,double turbidity) {}
    record Demand(String zone,String sector,int litersPerDay) {}
    private static final List<Asset> ASSETS=List.of(new Asset("RES-01","Reservoir","North basin"),new Asset("PLANT-07","Treatment plant","River gate"),new Asset("PIPE-14","Pipeline","East district"),new Asset("PUMP-02","Pumping station","Hill sector"));
    private static final List<Demand> DEMANDS=new ArrayList<>(List.of(new Demand("North","Residential",12000),new Demand("East","Agricultural",18000),new Demand("West","Industrial",9000)));
    private static final String REPORT="RES-01 sample: elevated turbidity; chlorine alert; pipeline PIPE-14 inspection. Elevated turbidity observed.";
    public static void main(String[]args){Scanner in=new Scanner(System.in);System.out.println("AquaNet | Smart Water Resource Management\nSample data loaded: 4 assets, 3 demand zones, quality report and sensor stream.");while(true){System.out.println("\n1 Overview  2 Quality & search  3 Report index  4 Planning DP  5 Network flow  6 Constraints  7 Sensor analytics  8 Exit");System.out.print("Select: ");String s=in.nextLine().trim();try{switch(s){case "1"->overview();case "2"->quality(in);case "3"->index();case "4"->planning();case "5"->network();case "6"->constraints();case "7"->sensors();case "8"->{System.out.println("AquaNet closed.");return;}default->System.out.println("Choose 1-8.");}}catch(Exception e){System.out.println("Could not complete operation: "+e.getMessage());}}}
    static void overview(){System.out.println("\nINFRASTRUCTURE");ASSETS.forEach(a->System.out.printf(" %-9s %-18s %s%n",a.id,a.type,a.location));System.out.println("\nDEMAND (liters/day)");DEMANDS.forEach(d->System.out.printf(" %-12s %-14s %,d%n",d.zone,d.sector,d.litersPerDay));System.out.println("Quality reports: 1 | active sensor observations: 5");}
    static void quality(Scanner in){System.out.print("Search quality report term (blank = turbidity): ");String term=in.nextLine();if(term.isBlank())term="turbidity";System.out.println("KMP positions: "+Algorithms.kmp(REPORT.toLowerCase(Locale.ROOT),term.toLowerCase(Locale.ROOT)));System.out.println("Rabin-Karp asset-ID matches: "+Algorithms.rabinKarp("RES-01 PLANT-07 PIPE-14 PUMP-02",term.toUpperCase(Locale.ROOT)));List<String> keys=List.of("turbidity","chlorine","contamination","leak");System.out.println("Aho-Corasick alerts: "+Algorithms.ahoCorasick(REPORT,keys));System.out.println("Z-function report pattern array: "+Arrays.toString(Algorithms.zFunction("turbidity#"+REPORT.toLowerCase(Locale.ROOT))));System.out.println("Typo correction suggestion for 'turbidty': turbidity (edit distance "+Algorithms.levenshtein("turbidty","turbidity",true)+")");}
    static void index(){String docs=String.join("$","Elevated turbidity at RES-01","Pipeline PIPE-14 inspection","Elevated turbidity observed","Chlorine alert at PLANT-07");int[]sa=Algorithms.suffixArraySAIS(docs),lcp=Algorithms.lcpKasai(docs,sa);System.out.println("SA-IS induced-sorting suffix-array indexed report text: "+docs.length()+" chars");System.out.println("SA: "+Arrays.toString(sa));System.out.println("Kasai LCP: "+Arrays.toString(lcp));System.out.println("Repeated descriptions (LCP >= 9): "+Arrays.stream(lcp).filter(x->x>=9).count());System.out.println("Suffix-array query 'turbidity': "+Algorithms.suffixSearch(docs,"turbidity"));System.out.println("Suffix-automaton query 'PIPE-14': "+Algorithms.suffixAutomatonContains(docs,"PIPE-14"));}
    static void planning(){System.out.println("Treatment units affordable within resource budget 12: "+Algorithms.treatmentSubset(new int[]{5,4,7,3},12));System.out.println("Analysis operation matrix-chain minimum scalar multiplications: "+Algorithms.matrixChain(new int[]{30,35,15,5,10,20,25}));System.out.println("Optimal-BST expected comparison cost for access frequencies: "+Algorithms.obstCost(new double[]{34,8,50,12}));System.out.println("Entry correction Damerau distance (turbidty → turbidity): "+Algorithms.levenshtein("turbidty","turbidity",true));}
    static void network(){int[][]e={{0,1,9},{0,2,8},{1,2,3},{1,3,5},{2,3,10},{3,4,12},{2,4,4}};System.out.println("Max water flow RES-01 → demand hub (Ford-Fulkerson/Edmonds-Karp): "+Algorithms.maxFlow(5,e,0,4,false)+" units");System.out.println("Max water flow via Dinic: "+Algorithms.maxFlow(5,e,0,4,true)+" units");System.out.println("Critical pipeline cut edges: "+Algorithms.minCut(5,e,0).stream().map(x->x[0]+"→"+x[1]+" ("+x[2]+")").toList());System.out.println("Treatment operator-to-unit assignments: "+Algorithms.matching(new int[][]{{0,1},{0},{1,2}},3)+" operators matched");}
    static void constraints(){int[][]clauses={{1,2,-3},{-1,2,3},{1,-2,3}};System.out.println("SAT/3-SAT resource constraints satisfiable: "+Algorithms.sat(3,clauses));System.out.println("3-SAT to CLIQUE compatibility edges: "+Algorithms.threeSatToClique(clauses).size());int[][]conflicts={{0,1},{1,2},{2,3},{0,3}};int[][]ind=Algorithms.cliqueToIndependent(4,conflicts);System.out.println("CLIQUE complement → independent-set graph edges: "+ind.length+"; its complement represents the vertex-cover instance.");System.out.println("2-approx critical pipeline vertex cover: "+Algorithms.vertexCoverApprox(4,conflicts));}
    static void sensors(){List<Integer> ranks=new ArrayList<>(List.of(12000,18000,9000,15000,11000));Algorithms.randomizedQuickSort(ranks,Integer::compare);System.out.println("Randomized QuickSort demand ranking (L/day): "+ranks);List<Observation> stream=List.of(new Observation("S1",88,7.2,1.1),new Observation("S2",91,7.1,0.9),new Observation("S3",76,6.8,2.3),new Observation("S4",83,7.0,1.5),new Observation("S5",79,7.3,1.2));System.out.println("Reservoir sample (k=3) of live sensor records: "+Algorithms.reservoir(stream,3,new Random()));long[]levels={88,91,76,83,79};System.out.println("Blelloch exclusive cumulative levels: "+Arrays.toString(Algorithms.blellochScan(levels)));double[]ph={7.2,7.1,6.8,7.0,7.3};System.out.println("Parallel Reduce mean pH: "+Algorithms.parallelReduce(ph));System.out.println("Miller-Rabin prime check (1,000,003): "+Algorithms.millerRabin(1_000_003,8));System.out.println("Brent work/span estimate for W=1,000,000, P=8: "+Algorithms.brentSpan(1_000_000,8));}
}

